public 
enum ClientError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * Nothing answered at the address: the daemon is not running.
     */
    case NotRunning(address: String
    )
    /**
     * The daemon answered that the request failed.
     */
    case Failed(message: String
    )
    /**
     * The answer was not what this client understands.
     */
    case Protocol(message: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension ClientError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeClientError: FfiConverterRustBuffer {
    typealias SwiftType = ClientError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ClientError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .NotRunning(
            address: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Failed(
            message: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Protocol(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: ClientError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .NotRunning(address):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(address, into: &buf)
            
        
        case let .Failed(message):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Protocol(message):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


